//! Emit [`super::generated`] from a fresh parse of the vendored `.S` — the
//! `@generated` codegen. **Test-only**. Produces compilable, mostly
//! fmt-clean Rust; the regen pipeline runs `cargo fmt` afterwards, so the
//! committed file is canonical and idempotent.

use std::collections::HashSet;
use std::fmt::Write as _;

use super::check::{BASE_X, MARK, ODD_X, THIN};
use super::FrameDef;

const HEADER: &str = "\
// @generated by `POP_ANIM_REGEN=1 cargo test -p pop-assets` — DO NOT EDIT.
// POP character-animation tables baked from the vendored Apple II source:
//   FRAMEDEF.S — 5-byte frame records, three sections (main / altset1 / altset2)
//   SEQTABLE.S — per-motion opcode streams walked into frame lists
// Regenerate with `task gen:anim`. The drift test
// `anim::tests::generated_matches_a_fresh_parse` fails CI if this is stale.

use super::check::{MARK, ODD_X, THIN};
use super::{AnimFrame, AnimSequence, FrameDef};

";

/// Render the full `generated.rs` source text from the parsed tables.
pub(super) fn render_generated() -> String {
    let sections = super::parse::parse_framedef();
    let seqs = super::parse::parse_sequences();

    // `SECTIONS` below references all three statics, so the parse must yield
    // them — else the generated file would name undeclared statics. (The
    // parser normally returns >3: the 3 used + empty trailing `ds` sections.)
    assert!(
        sections.len() >= 3,
        "expected >=3 FRAMEDEF sections, got {} — the .S layout changed",
        sections.len()
    );

    let mut out = String::from(HEADER);

    // FRAMEDEF sections — only the three the runtime uses (main + the two
    // alternates); the parser also yields empty trailing `ds` sections.
    let names = ["MAIN", "ALTSET1", "ALTSET2"];
    for (name, section) in names.iter().zip(&sections) {
        let _ = writeln!(out, "static {name}: &[FrameDef] = &[");
        for f in section {
            if *f == FrameDef::EMPTY {
                out.push_str("    FrameDef::EMPTY,\n");
            } else {
                let _ = writeln!(
                    out,
                    "    FrameDef::new({:#04x}, {:#04x}, {}, {}, {}),",
                    f.image,
                    f.sword,
                    f.dx,
                    f.dy,
                    format_check(f.check),
                );
            }
        }
        out.push_str("];\n\n");
    }
    out.push_str("pub(super) static SECTIONS: [&[FrameDef]; 3] = [MAIN, ALTSET1, ALTSET2];\n\n");

    // A unique `F_<NAME>` identifier per sequence with frames.
    let mut used: HashSet<String> = HashSet::new();
    let ids: Vec<String> = seqs
        .iter()
        .map(|s| {
            let base = format!("F_{}", sanitize(&s.name));
            let mut id = base.clone();
            let mut n = 1;
            while !used.insert(id.clone()) {
                id = format!("{base}_{n}");
                n += 1;
            }
            id
        })
        .collect();

    // Per-sequence frame lists (empty sequences are inlined as `&[]`).
    for (s, id) in seqs.iter().zip(&ids) {
        if s.frames.is_empty() {
            continue;
        }
        let _ = writeln!(out, "static {id}: &[AnimFrame] = &[");
        for f in &s.frames {
            let action = f
                .action
                .map_or_else(|| "None".to_string(), |a| format!("Some({a})"));
            let turn = if f.turn { ".with_turn()" } else { "" };
            let _ = writeln!(
                out,
                "    AnimFrame::new({}, {}, {}, {action}){turn},",
                f.frame, f.dx, f.dy,
            );
        }
        out.push_str("];\n\n");
    }

    // The sequence table, in id order.
    out.push_str("pub(super) static SEQUENCES: &[AnimSequence] = &[\n");
    for (s, id) in seqs.iter().zip(&ids) {
        let frames = if s.frames.is_empty() { "&[]" } else { id };
        let loops_to = s
            .loops_to
            .map_or_else(|| "None".to_string(), |l| format!("Some({l})"));
        let chains_to = s
            .chains_to
            .as_ref()
            .map_or_else(|| "None".to_string(), |c| format!("Some({c:?})"));
        let _ = writeln!(
            out,
            "    AnimSequence::new({}, {:?}, {frames}, {loops_to}, {chains_to}),",
            s.id, s.name,
        );
    }
    out.push_str("];\n");

    out
}

/// Format an `Fcheck` byte as a flag-OR expression: the set named flag bits
/// (bits 5-7) plus the base-X residual (bits 0-4) as a decimal term. Those
/// cover all 8 bits, so every byte decomposes — no hex fallback needed.
fn format_check(byte: u8) -> String {
    let mut parts: Vec<String> = Vec::new();
    if byte & ODD_X != 0 {
        parts.push("ODD_X".to_string());
    }
    if byte & MARK != 0 {
        parts.push("MARK".to_string());
    }
    if byte & THIN != 0 {
        parts.push("THIN".to_string());
    }
    let base = byte & BASE_X;
    if parts.is_empty() {
        // No flags: the base is the whole value, a plain literal.
        parts.push(base.to_string());
    } else if base != 0 {
        // The base joins a bitwise OR — hex, so clippy doesn't flag a decimal
        // literal in a bit expression.
        parts.push(format!("{base:#04x}"));
    }
    parts.join(" | ")
}

/// Uppercase a sequence name into a Rust identifier body (non-alphanumeric
/// → `_`), for the `F_<NAME>` frame statics.
fn sanitize(name: &str) -> String {
    name.chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() {
                c.to_ascii_uppercase()
            } else {
                '_'
            }
        })
        .collect()
}
